static class Pair<K, V> {
    private final K key;
    private final V value;
    Pair(K key, V value) { this.key = key; this.value = value; }
    K getKey() { return key; }
    V getValue() { return value; }
}
Pair<String, Integer> nameAndAge = new Pair<>("Kasia", 29);

static <T> T firstNonNull(T a, T b) {
    return (a != null) ? a : b;
}
String result = firstNonNull(null, "domyslny"); // T wywnioskowane jako String

static class Wrapper {
    <T> Wrapper(T value) { /* generyczny konstruktor */ }
}

interface Container<T> {
    void put(T value);
    T get();
}
static class SimpleContainer<T> implements Container<T> {
    private T stored;
    public void put(T value) { this.stored = value; }
    public T get() { return stored; }
}
